package dev.admutium.techmod.client.suit;
import dev.admutium.techmod.TechMod;import dev.admutium.techmod.suit.*;import dev.admutium.techmod.energy.Energy;import dev.admutium.techmod.machine.*;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.keymapping.v1.KeyMappingHelper;import net.fabricmc.fabric.api.client.networking.v1.*;import net.fabricmc.fabric.api.client.rendering.v1.hud.HudElementRegistry;
import net.minecraft.client.*;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.screens.inventory.InventoryScreen;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.world.entity.*;import net.minecraft.world.entity.monster.Monster;import net.minecraft.world.item.*;import net.minecraft.world.level.block.CropBlock;import net.minecraft.world.phys.*;
import org.joml.Vector3f;import org.joml.Quaternionf;import java.util.*;
public final class SuitClient {
 public static SuitData data=SuitData.EMPTY;public static long[] rates=new long[5];public static int warp;public static long stationEnergy,stationIn,chargeRate;public static float bank;private static BlockPos wirePos=BlockPos.ZERO;private static long wireRate;public static KeyMapping playerList;private static float lastYaw;private static int input=-1;
 public static final net.fabricmc.fabric.api.client.rendering.v1.RenderStateDataKey<Boolean> SPRINT=net.fabricmc.fabric.api.client.rendering.v1.RenderStateDataKey.create();
 public static final net.fabricmc.fabric.api.client.rendering.v1.RenderStateDataKey<SuitData> VISUAL=net.fabricmc.fabric.api.client.rendering.v1.RenderStateDataKey.create();
 private static final Map<BlockPos,Integer> ores=new LinkedHashMap<>();private static final List<BlockPos> OFFSETS=new ArrayList<>();private static BlockPos origin=BlockPos.ZERO;private static int cursor;private static boolean scanning;
 public static void init(){for(int x=-25;x<=25;x++)for(int y=-25;y<=25;y++)for(int z=-25;z<=25;z++)if(x*x+y*y+z*z<=625)OFFSETS.add(new BlockPos(x,y,z));OFFSETS.sort(Comparator.comparingDouble(p->p.distSqr(BlockPos.ZERO)));
  ClientPlayNetworking.registerGlobalReceiver(SuitPackets.Wire.TYPE,(packet,ctx)->ctx.client().execute(()->{wirePos=packet.pos();wireRate=packet.rate();}));
  ClientPlayNetworking.registerGlobalReceiver(SuitPackets.State.TYPE,(packet,ctx)->ctx.client().execute(()->{if(ctx.client().player!=null&&(!packet.worn().isEmpty()||!Suits.worn(ctx.client().player).isEmpty()))ctx.client().player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST,packet.worn().copy());data=packet.stack().getOrDefault(Suits.DATA,SuitData.EMPTY);rates=packet.rates();warp=packet.warp();stationEnergy=packet.stationEnergy();stationIn=packet.stationIn();chargeRate=packet.charging();}));
  Suits.clientData=p->{var item=Suits.worn(p).getOrDefault(Suits.DATA,SuitData.EMPTY);return Minecraft.getInstance().player!=null&&p.getUUID().equals(Minecraft.getInstance().player.getUUID())&&item.id().equals(data.id())?data:item;};
  net.minecraft.client.gui.screens.MenuScreens.register(Suits.STATION_MENU,SuitStationScreen::new);net.minecraft.client.gui.screens.MenuScreens.register(Suits.INVENTORY_MENU,SuitInventoryScreen::new);net.minecraft.client.renderer.entity.EntityRenderers.register(Suits.REMAINS,SuitRemainsRenderer::new);
  var tab=KeyMappingHelper.registerKeyMapping(new KeyMapping("key.techmod.suit_menu",258,KeyMapping.Category.MISC));var magnet=KeyMappingHelper.registerKeyMapping(new KeyMapping("key.techmod.suit_magnet",86,KeyMapping.Category.MISC));playerList=KeyMappingHelper.registerKeyMapping(new KeyMapping("key.techmod.suit_players",96,KeyMapping.Category.MISC));
  ClientTickEvents.END_CLIENT_TICK.register(c->{if(c.player==null)return;boolean worn=!Suits.worn(c.player).isEmpty();while(tab.consumeClick())if(worn&&c.gui.screen()==null)c.setScreenAndShow(new SuitRadialScreen());while(magnet.consumeClick())if(worn&&c.gui.screen()==null)action("toggle","magnet_pulse");
   if(worn){int bits=c.gui.screen()==null?(c.options.keyJump.isDown()?1:0)|(c.options.keyShift.isDown()?2:0)|(c.options.keySprint.isDown()?4:0):0;if(bits!=input){input=bits;action("input",Integer.toString(bits));}predict(c);scan(c);}else{input=-1;ores.clear();scanning=false;}
   float dy=net.minecraft.util.Mth.wrapDegrees(c.player.getYRot()-lastYaw);lastYaw=c.player.getYRot();var d=Suits.data(c.player);boolean flying=worn&&d.energy()>0&&(c.player.isFallFlying()||d.on("flight_gravity")||d.on("flight_jet")&&!c.player.onGround());float target=flying?Math.clamp(-dy*.65f,-13,13):0;bank+=(target-bank)*.18f;
  });
  HudElementRegistry.addLast(TechMod.id("suit_hud"),(g,dt)->hud(g));ClientPlayConnectionEvents.DISCONNECT.register((h,c)->{data=SuitData.EMPTY;rates=new long[5];ores.clear();bank=0;});
 }
 public static void action(String key,String value){ClientPlayNetworking.send(new SuitPackets.Action(key,value,-1));}
 public static SuitData wornData(){var c=Minecraft.getInstance();return c.player==null?SuitData.EMPTY:Suits.data(c.player);}
 static void predict(Minecraft c){var p=c.player;var d=wornData();if(d.energy()==0)return;if(d.on("flight_jet")&&(input&1)!=0&&!p.onGround()){var v=p.getDeltaMovement();p.setDeltaMovement(v.x,Math.min(.65,v.y+.14),v.z);p.resetFallDistance();}if(d.on("flight_elytra")&&p.isFallFlying()&&p.isSprinting()){var v=p.getDeltaMovement().add(p.getLookAngle().scale(.055));if(v.length()>1.65)v=v.normalize().scale(1.65);p.setDeltaMovement(v);}}
 static void scan(Minecraft c){var d=wornData();if(!d.on("ore_scan")||d.energy()==0){ores.clear();scanning=false;return;}var center=c.player.blockPosition();if(!scanning||center.distSqr(origin)>16){origin=center;cursor=0;scanning=true;ores.entrySet().removeIf(e->e.getKey().distSqr(center)>625);}int checks=0;while(checks++<1536){if(cursor>=OFFSETS.size()){cursor=0;origin=center;}var pos=origin.offset(OFFSETS.get(cursor++));if(!c.level.hasChunkAt(pos)||pos.distSqr(center)>625)continue;var state=c.level.getBlockState(pos);String id=BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString();boolean match=SuitRuntime.ore(state)&&(d.contents().ores().isEmpty()||d.contents().ores().contains(id));if(match&&ores.size()<256)ores.put(pos.immutable(),oreColor(id));else if(!match)ores.remove(pos);}ores.entrySet().removeIf(e->e.getKey().distSqr(center)>625||!SuitRuntime.ore(c.level.getBlockState(e.getKey())));}
 static int oreColor(String id){if(id.contains("diamond"))return 0xff4de9ee;if(id.contains("gold"))return 0xffffda42;if(id.contains("redstone"))return 0xffff4545;if(id.contains("copper"))return 0xffff9650;if(id.contains("emerald"))return 0xff49f985;if(id.contains("lapis"))return 0xff6695ff;if(id.contains("iron"))return 0xffe5c8b1;if(id.contains("tin"))return 0xffb3d7db;return 0xffdedee5;}
 static int[] project(Vec3 pos){var c=Minecraft.getInstance();var camera=c.gameRenderer.mainCamera();var rel=pos.subtract(camera.position());var v=new Vector3f((float)rel.x,(float)rel.y,(float)rel.z).rotate(new Quaternionf(camera.rotation()).conjugate());if(v.z>=-.1)return null;int w=c.getWindow().getGuiScaledWidth(),h=c.getWindow().getGuiScaledHeight();double focal=h/(2*Math.tan(Math.toRadians(camera.getFov())/2));int x=(int)(w/2+v.x*focal/-v.z),y=(int)(h/2-v.y*focal/-v.z);return x<4||x>w-4||y<4||y>h-4?null:new int[]{x,y};}
 static void marker(GuiGraphicsExtractor g,Vec3 pos,int color,boolean enemy){var xy=project(pos);if(xy==null)return;int x=xy[0],y=xy[1],r=enemy?5:3;g.fill(x-r,y-r,x+r+1,y-r+1,color);g.fill(x-r,y+r,x+r+1,y+r+1,color);g.fill(x-r,y-r,x-r+1,y+r+1,color);g.fill(x+r,y-r,x+r+1,y+r+1,color);}
 static void hud(GuiGraphicsExtractor g){var c=Minecraft.getInstance();if(c.player==null||Suits.worn(c.player).isEmpty()||c.gui.hud.isHidden())return;var p=c.player;var d=wornData();int x=9,y=9;long total=Arrays.stream(rates).sum();g.fill(x-3,y-3,x+210,y+57,0xb8101921);g.text(c.font,"КОНТУР  "+Energy.format(d.energy())+" / "+Energy.format(d.capacity())+" ТЕ",x,y,0xffffbd67);g.fill(x,y+12,x+200,y+17,0xff15222a);g.fill(x,y+12,x+(int)(200*d.energy()/d.capacity()),y+17,0xffe6a64c);g.text(c.font,"−"+Energy.format(total,c.hasShiftDown())+" / +"+Energy.format(chargeRate,c.hasShiftDown())+" ТЕ/с   [Tab]",x,y+22,0xffc7d9e5);int used=0;for(int i=0;i<36;i++)if(!p.getInventory().getItem(i).isEmpty())used++;for(var item:d.contents().cargo())if(!item.isEmpty())used++;g.text(c.font,"Инвентарь "+used+" / "+(36+(d.level(SuitUpgrade.INVENTORY)>0?9:0))+"   Щит "+(d.shield()/1000),x,y+36,0xffb0dacf);g.text(c.font,"Капсулы: "+d.contents().nutrients(),x,y+48,0xffb8c6d1);
  if(warp>0)g.text(c.font,"Варп: "+String.format(Locale.ROOT,"%.1f",warp/20.)+" с",c.getWindow().getGuiScaledWidth()/2-40,65,0xffffc26b);
  if(d.energy()>0){if(d.on("ore_scan"))for(var e:ores.entrySet())marker(g,Vec3.atCenterOf(e.getKey()),e.getValue(),false);if(d.on("enemy_scan")){int count=0;for(var entity:c.level.getEntitiesOfClass(Monster.class,p.getBoundingBox().inflate(25))){if(count++>=64)break;if(entity.distanceToSqr(p)<=625)marker(g,entity.getEyePosition(),0xffff7968,true);}}
   if(d.level(SuitUpgrade.TARGET)>0&&c.hitResult instanceof EntityHitResult hit&&hit.getEntity() instanceof LivingEntity living){int tx=c.getWindow().getGuiScaledWidth()/2,ty=c.getWindow().getGuiScaledHeight()/2+24;g.text(c.font,living.getName().getString()+"  "+String.format(Locale.ROOT,"%.1f / %.1f",living.getHealth(),living.getMaxHealth()),tx-70,ty,0xffff9c83);g.fill(tx-50,ty+12,tx+50,ty+17,0xff452c2c);g.fill(tx-50,ty+12,tx-50+(int)(100*living.getHealth()/living.getMaxHealth()),ty+17,0xffd67c66);}
   visor(g,c,d);
  }
 }
 static void visor(GuiGraphicsExtractor g,Minecraft c,SuitData d){if(!(c.hitResult instanceof BlockHitResult hit))return;var pos=hit.getBlockPos();int x=9,y=82;if(d.level(SuitUpgrade.VISOR)>0&&c.level.getBlockEntity(pos) instanceof MachineBlockEntity be){g.text(c.font,be.getDisplayName().getString()+": "+Energy.format(be.stored())+" / "+Energy.format(be.capacity())+" ТЕ",x,y,0xffa8d6e7);g.text(c.font,"Вход "+Energy.format(be.displayIn,true)+" / Выход "+Energy.format(be.displayOut,true)+" ТЕ/с",x,y+12,0xffa8d6e7);}else if(d.level(SuitUpgrade.VISOR)>0&&c.level.getBlockState(pos).is(TechMod.CABLE))g.text(c.font,"Провод: "+Energy.format(pos.equals(wirePos)?wireRate:0,true)+" / 10 ТЕ/с (макс. по граням)",x,y,0xffa8d6e7);
  if(d.level(SuitUpgrade.PLANT)>0){var state=c.level.getBlockState(pos);if(state.getBlock() instanceof CropBlock crop){g.text(c.font,"Рост: "+(100*crop.getAge(state)/crop.getMaxAge())+"%",x,y,0xffa6e890);}}
 }
 public static String homeText(){var d=wornData();if(d.level(SuitUpgrade.COMPASS)==0)return "Компас не открыт";if(d.home().isEmpty())return "Нет домашней станции";var home=d.home().get();var p=Minecraft.getInstance().player;if(!p.level().dimension().equals(home.dimension()))return "Станция в другом измерении";var delta=Vec3.atCenterOf(home.pos()).subtract(p.position());double angle=net.minecraft.util.Mth.wrapDegrees((float)(Math.toDegrees(Math.atan2(-delta.x,delta.z))-p.getYRot()));String dir=Math.abs(angle)<23?"↑":angle>23&&angle<157?"→":angle< -23&&angle> -157?"←":"↓";return dir+" Станция: "+(int)delta.length()+" м";}
}
